import{_ as n,a0 as o,w as s,s as p,ao as d,I as l,x as a,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"5 分鐘內瞭解 OSI 模型 | LCTT x X-CMD","titleTemplate":false,"description":"5 分鐘內瞭解 OSI 模型 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 分鐘內瞭解 OSI 模型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 分鐘內瞭解 OSI 模型 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221004 Learn the OSI model in 5 minutes","title":"5 分鐘內瞭解 OSI 模型","tag":"202212","desc":""},"relativePath":"202212/20221004 Learn the OSI model in 5 minutes.md","filePath":"[post].md"}'),m={name:"202212/20221004 Learn the OSI model in 5 minutes.md"};function h(u,e,f,b,I,S){const t=o("Link");return s(),p("div",null,[e[15]||(e[15]=d('<h1 id="_5-分鐘內瞭解-osi-模型" tabindex="-1">5 分鐘內瞭解 OSI 模型 <a class="header-anchor" href="#_5-分鐘內瞭解-osi-模型" aria-label="Permalink to “5 分鐘內瞭解 OSI 模型”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/16/092612etn6gwaecb91bweg.jpg" alt=""></p><blockquote><p>理解 OSI 框架的基本概念，掌握計算機系統通信機制。</p></blockquote><p><ruby>開放系統互聯<rt>Open Systems Interconnection</rt></ruby>（OSI）模型是一個定義計算機、服務器和用户如何在一個系統內通信的標準。它是第一個網絡通信標準模型，在上世紀 80 年代早期，所有主流的計算機和通信公司都採用了這個標準。</p><p>OSI 模型提供了一種用於描述網絡的通用語言，並以離散的塊或層的方式來描述。</p><h3 id="osi-模型的各個層" tabindex="-1">OSI 模型的各個層 <a class="header-anchor" href="#osi-模型的各個層" aria-label="Permalink to “OSI 模型的各個層”">​</a></h3><p>該模型描述了計算機系統通過網絡進行通信的七個層。</p><ul><li>7 應用層</li><li>6 表示層</li><li>5 會話層</li><li>4 傳輸層</li><li>3 網絡層</li><li>2 數據鏈路層</li><li>1 物理層</li></ul><p>每個層都有自己的工作方式和一系列跟其他層不同的協議。本文將逐個剖析這些層級。</p><h3 id="應用層" tabindex="-1">應用層 <a class="header-anchor" href="#應用層" aria-label="Permalink to “應用層”">​</a></h3><p>應用層是在軟件中實現的。它是與應用程序交互的層級。</p><p>用發送消息作為例子。發送消息的程序與應用層進行交互，併發送消息。接着，應用層向 OSI 模型的下一個層級（即表示層）發送消息。</p><h3 id="表示層" tabindex="-1">表示層 <a class="header-anchor" href="#表示層" aria-label="Permalink to “表示層”">​</a></h3><p>來自應用層的數據被轉發到表示層。表示層接收到文字、字符、字母、數字等形式的數據，並把它們轉換為機器可識讀的二進制格式數據。這個過程叫做編譯。</p><p>在此階段，ASCII（美國信息交換標準碼）字符被轉換為擴充的二進制編碼的十進制交換碼（EBCDIC）。轉換後的數據在繼續傳輸前，也會進行編碼和加密過程，使用 SSL 協議進行加密和解密。</p><p>表示層的作用是抽象化，它假設下面的層級會處理它們收到的數據。它也負責壓縮數據。數據的壓縮可能是有損的，也有可能是無損的，這取決於很多因素，這不屬於本文的討論範圍。</p><h3 id="會話層" tabindex="-1">會話層 <a class="header-anchor" href="#會話層" aria-label="Permalink to “會話層”">​</a></h3><p>會話層的作用是建立和管理連接。該層級的主要工作是建立會話。例如，你登錄網上商城，就在你的機器和服務器之間建立了會話。</p><p>會話層的作用是實現數據的發送和接收，完成後連接的會話就終止了。在一個會話建立前，會進行身份驗證。與上一層類似，會話層也假設在它的工作完成後，下面的層級也會準確無誤地處理數據。</p><h3 id="傳輸層" tabindex="-1">傳輸層 <a class="header-anchor" href="#傳輸層" aria-label="Permalink to “傳輸層”">​</a></h3><p>傳輸層的作用是管理數據傳輸和其自身的關於數據如何傳輸的一些協議。從會話層傳到這裏的數據被分為更小的數據單元，這些數據單元稱為片段。這個過程叫做“分段”。每個片段包含來源端口號、目標端口號和一個序列號。端口號用來識別發送數據的應用程序。注意，數據以塊的形式傳輸。序列號用於把這些片段按正確的順序排列。</p><p>傳輸層負責控制流量或在給定的時間內傳輸的數據量。它也負責錯誤控制，比如數據丟失、損壞等情況。它利用一種錯誤檢測值，通常叫做校驗和。傳輸層對每個數據片段加上校驗和，就可以檢查所發送的數據是否被正確接收。然後數據傳輸到網絡層。</p><h3 id="網絡層" tabindex="-1">網絡層 <a class="header-anchor" href="#網絡層" aria-label="Permalink to “網絡層”">​</a></h3><p>網絡層的作用是跟其他網絡進行通信。它把從一台機器接收到的數據片段傳輸給另一台位於不同網絡的機器。路由器是作用於網絡層的。</p><p>網絡層的功能是邏輯尋址（就是確定 IP 地址）。它為發送方和接收方分配 IP 地址，數據包附帶了這個地址，就可以被傳輸到正確的目標機器。接着網絡層對數據包進行路由。負載均衡也是在網絡層進行的，旨在確保不會發生過載。下一步，數據傳輸到數據鏈路層。</p><h3 id="數據鏈路層" tabindex="-1">數據鏈路層 <a class="header-anchor" href="#數據鏈路層" aria-label="Permalink to “數據鏈路層”">​</a></h3><p>數據鏈路層支持跟其他設備直接通信。</p><p>它接收到來自網絡層、包含發送方和接收方 IP 地址的數據包，進行物理尋址，然後將發送方和接收方的 MAC 地址分配給數據包，形成幀。</p><h3 id="物理層" tabindex="-1">物理層 <a class="header-anchor" href="#物理層" aria-label="Permalink to “物理層”">​</a></h3><p>物理層由系統的所有硬件和物理設備（包括網線、導航系統、適配器等）組成。在這裏，從前面層級接收到的數據都是 0 和 1 形式的。物理層把這些數據轉換並通過各種方式（如果是光纖電纜，有電線、電信號、光信號；如果是 WIFI，則為無線電信號）傳輸至本地媒介。</p><p>注意，物理層作用於接收方的一端，把接收到的信號以幀的形式傳輸到數據鏈路層（把它轉換回二進制數據形式）。然後幀傳輸到上面的層級，最終應用層（應用軟件）會接收到需要的數據。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>當你需要描述網絡架構或排除網絡問題時，OSI 模型的相關知識會對你有所幫助。我希望本文能令你對這個模型的方方面面有清晰的理解。</p><hr>',34)),l("p",null,[e[1]||(e[1]=a("via: ",-1)),i(t,{href:"https://opensource.com/article/22/10/osi-model-network-communications"},{default:r(()=>[...e[0]||(e[0]=[a("https://opensource.com/article/22/10/osi-model-network-communications",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=a("作者：",-1)),i(t,{href:"https://opensource.com/users/anamika"},{default:r(()=>[...e[2]||(e[2]=[a("Anamika",-1)])]),_:1}),e[7]||(e[7]=a(" 選題：",-1)),i(t,{href:"https://github.com/lkxed"},{default:r(()=>[...e[3]||(e[3]=[a("lkxed",-1)])]),_:1}),e[8]||(e[8]=a(" 譯者：",-1)),i(t,{href:"https://github.com/cool-summer-021"},{default:r(()=>[...e[4]||(e[4]=[a("cool-summer-021",-1)])]),_:1}),e[9]||(e[9]=a(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[a("Linux中國",-1)])]),_:1}),e[14]||(e[14]=a(" 榮譽推出",-1))])])}const C=n(m,[["render",h]]);export{k as __pageData,C as default};
